(635272, 66026, 4285, '<td valign="top">Spectra-Precision/Geodimeter. I use one similar to this where I work but it''s more yellow.</td>', 'Spectra-Precision/Geodimeter. I use one similar to this where I work but it''s more yellow.', '2004-03-24 08:47:09.000000', NULL, 1),
(635274, 66010, 18868, '<td valign="top">This image would have scored 2 pts better if it had been sharp.  Got Tripod?</td>', 'This image would have scored 2 pts better if it had been sharp.  Got Tripod?', '2004-03-24 08:47:52.000000', NULL, 1),
