(640325, 65550, 18191, '<td valign="top">This shot was good except for the shadow on the bottom of the cup and the reflection in the orange soup.</td>', 'This shot was good except for the shadow on the bottom of the cup and the reflection in the orange soup.', '2004-03-26 20:25:02.000000', NULL, 1),
(640326, 66121, 18191, '<td valign="top">Great shot, but i would have rather had the whole butterfly in focus instead of the flower.</td>', 'Great shot, but i would have rather had the whole butterfly in focus instead of the flower.', '2004-03-26 20:25:38.000000', NULL, 1),
(640327, 65463, 18191, '<td valign="top">Freaky, but intriguing.</td>', 'Freaky, but intriguing.', '2004-03-26 20:25:51.000000', NULL, 1),
