(641580, 65357, 10593, '<td valign="top">orange you glad i''m giving you an 8 :)</td>', 'orange you glad i''m giving you an 8 :)', '2004-03-28 16:50:40.000000', NULL, 1),
(641586, 66414, 18073, '<td valign="top">Nice bold image, looks great against the blue backdrop</td>', 'Nice bold image, looks great against the blue backdrop', '2004-03-28 17:00:11.000000', NULL, 1),
(641588, 65544, 10047, '<td valign="top">Not sure I''ve ever had carrots and escargot in the same meal. Nice contrast and composition.</td>', 'Not sure I''ve ever had carrots and escargot in the same meal. Nice contrast and composition.', '2004-03-28 17:15:55.000000', NULL, 1),
(641591, 65554, 10047, '<td valign="top">Nice composition and contrast. The black frame works well with the lines on the ball. I have one of the other B-Ball pictures and wished I''d used a lighter background like yours. Hope yours is doing better than mine.</td>', 'Nice composition and contrast. The black frame works well with the lines on the ball. I have one of the other B-Ball pictures and wished I''d used a lighter background like yours. Hope yours is doing better than mine.', '2004-03-28 17:19:53.000000', NULL, 1),
(641595, 66223, 10047, '<td valign="top">Lots of detail and clarity on the bottom half of the duck, but the top seems a bit bright. Still an excellent photo.</td>', 'Lots of detail and clarity on the bottom half of the duck, but the top seems a bit bright. Still an excellent photo.', '2004-03-28 17:26:03.000000', NULL, 1),
(641600, 65952, 10047, '<td valign="top">Would have liked to seen a tighter crop, but it is still an excellent photo. Nice array of colors.</td>', 'Would have liked to seen a tighter crop, but it is still an excellent photo. Nice array of colors.', '2004-03-28 17:28:14.000000', NULL, 1),
(641602, 66314, 10047, '<td valign="top">Beautiful blossoms and a really well done photo. Excellent composition, contrast, and clarity.</td>', 'Beautiful blossoms and a really well done photo. Excellent composition, contrast, and clarity.', '2004-03-28 17:29:59.000000', NULL, 1),
(641606, 66197, 10047, '<td valign="top">This challenge sure is making me hungry. Nice variety of oranges.</td>', 'This challenge sure is making me hungry. Nice variety of oranges.', '2004-03-28 17:31:38.000000', NULL, 1),
(641607, 66408, 16255, '<td valign="top">Great shot, but it hits me more as red and yellow, separately, not as a mixture that says orange.</td>', 'Great shot, but it hits me more as red and yellow, separately, not as a mixture that says orange.', '2004-03-28 17:33:53.000000', NULL, 1),
(641612, 65683, 18709, '<td valign="top">I''ve looked and looked, but I can''t make out what this is.  Never mind, it''s good.</td>', 'I''ve looked and looked, but I can''t make out what this is.  Never mind, it''s good.', '2004-03-28 17:49:42.000000', NULL, 1),
