INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(643624, 66393, 2610, '<td valign="top">Good concept but the slided egg needs a little clean-up on the white where cut to give a starker organce genter IMO.  Very good though!</td>', 'Good concept but the slided egg needs a little clean-up on the white where cut to give a starker organce genter IMO.  Very good though!', '2004-03-30 09:17:40.000000', NULL, 1),
(643625, 66141, 2610, '<td valign="top">I like the concept</td>', 'I like the concept', '2004-03-30 09:18:45.000000', NULL, 1),
(643632, 66343, 14614, '<td valign="top">I really like the abstract quality of your shot.  It''s one of my ribbon picks.</td>', 'I really like the abstract quality of your shot.  It''s one of my ribbon picks.', '2004-03-30 09:40:11.000000', NULL, 1),
(643633, 66210, 14614, '<td valign="top">That''s an orange sky!  The dark tree sets the foreground and the distant hills gives me a sense of proportion.  One of my favorites this challenge</td>', 'That''s an orange sky!  The dark tree sets the foreground and the distant hills gives me a sense of proportion.  One of my favorites this challenge', '2004-03-30 09:41:07.000000', NULL, 1),
(643634, 65164, 14614, '<td valign="top">I like what you''ve done here (hope others do as well) very unique.  Has the feel of a painting.  One of my favorites this time around</td>', 'I like what you''ve done here (hope others do as well) very unique.  Has the feel of a painting.  One of my favorites this time around', '2004-03-30 09:41:59.000000', NULL, 1),
(643636, 66246, 14614, '<td valign="top">Lovely portrait - the veil covering (but not quite) the subject''s face really work.  Minor point - the backdrop seems to clash with the wonderful tones of the scarf and shirt (orange is a tough color to match)  The black part of the frame could be a bit thinner as it competes with the subject vs. compliemnt.</td>', 'Lovely portrait - the veil covering (but not quite) the subject''s face really work.  Minor point - the backdrop seems to clash with the wonderful tones of the scarf and shirt (orange is a tough color to match)  The black part of the frame could be a bit thinner as it competes with the subject vs. compliemnt.', '2004-03-30 09:44:38.000000', NULL, 1),
(643637, 66429, 14614, '<td valign="top">Excellent dof and creative play on the theme.  one of my favorites for it''s unique subject matter and fine execution.</td>', 'Excellent dof and creative play on the theme.  one of my favorites for it''s unique subject matter and fine execution.', '2004-03-30 09:45:33.000000', NULL, 1),
(643639, 65518, 14614, '<td valign="top">wonderful feel you''ve created, soft focus on the boat is great.  I think I''d prefer to have less dark foreground (either less of it or same amount but w/ some detail), would suggest removing some of the noise in the sky.  As presented, nicely done</td>', 'wonderful feel you''ve created, soft focus on the boat is great.  I think I''d prefer to have less dark foreground (either less of it or same amount but w/ some detail), would suggest removing some of the noise in the sky.  As presented, nicely done', '2004-03-30 09:48:00.000000', NULL, 1),
(643640, 66375, 14614, '<td valign="top">(first let me say that''s I''m biased towards flowers) you''ve done a fine job here with dof and the close-in angle and croping.  One of my ribbon picks.</td>', '(first let me say that''s I''m biased towards flowers) you''ve done a fine job here with dof and the close-in angle and croping.  One of my ribbon picks.', '2004-03-30 09:49:20.000000', NULL, 1),
(643641, 65993, 14614, '<td valign="top">such a serene mood and lovely monochromatic treatment... one of my favorites (to move it to one of my ribbon picks I''d suggest softening the 1/3, 1/3, 1/3 composition -- somehow the water line and the orange line in the sky is too linear for the mood you''ve created - hope that makes sense...)</td>', 'such a serene mood and lovely monochromatic treatment... one of my favorites (to move it to one of my ribbon picks I''d suggest softening the 1/3, 1/3, 1/3 composition -- somehow the water line and the orange line in the sky is too linear for the mood you''ve created - hope that makes sense...)', '2004-03-30 09:51:26.000000', NULL, 1),
(643647, 65989, 15711, '<td valign="top">I like the the fact that you captured the orange clouds before the actual horizon has turned color.</td>', 'I like the the fact that you captured the orange clouds before the actual horizon has turned color.', '2004-03-30 10:11:52.000000', NULL, 1),
